UPDATED_RE = re.compile(r"\b(last\s+)?(updat\w*|reviewed|modified|effective|closing|closes|until)\b", re.I)
ABOUT_RE = re.compile(r"^about\s+(us|the port|port of kestrel bay)\b", re.I)
JOB_WORDS = {
