    else:
        blocks = [("p", _clean_ws(part)) for part in re.split(r"\n\s*\n", html)]
        blocks = [(name, text) for name, text in blocks if text]

    paragraphs = []
    last = len(blocks) - 1
    for index, (name, text) in enumerate(blocks):
        if name in HEADINGS and ABOUT_HEADING.match(text):
            break
