_JUNK = (".share-bar, .newsletter-box, .related-posts, .inline-related, .post-tags, "
         ".post-meta, [class*='related'], [class*='share'], [class*='newsletter'], "
         "[class*='tags'], [class*='about'], [class*='contact'], [class*='cookie'], "
         "script, style, noscript, form, aside, nav, footer")
